<?php require_once __DIR__.'/config/config.php'; require_once __DIR__.'/includes/functions.php'; $pageTitle='Actualités'; $items=$pdo->query("SELECT title,slug,summary,published_at FROM news WHERE status='published' ORDER BY published_at DESC,id DESC")->fetchAll(); include __DIR__.'/includes/header.php'; ?>
<section class="page-banner"><div class="container"><span class="eyebrow">INFORMATIONS</span><h1>Actualités</h1><p>Les dernières informations et publications institutionnelles.</p></div></section><section class="section"><div class="container cards-grid"><?php foreach($items as $n): ?><article class="content-card"><div class="card-body"><span class="date"><?=e($n['published_at']?date('d/m/Y',strtotime($n['published_at'])):'')?></span><h3><?=e($n['title'])?></h3><p><?=e($n['summary'])?></p><a class="text-link" href="article.php?slug=<?=urlencode($n['slug'])?>">Lire la suite →</a></div></article><?php endforeach; ?><?php if(!$items): ?><p class="muted">Aucune actualité publiée.</p><?php endif; ?></div></section>
